include "globals.mzn";

enum COLOR = {Red, Blue, Green, Ivory, Yellow};
enum NATIONALITY = {Englishman, Spaniard, Ukrainian, Norwegian, Japanese};
enum DRINK = {Milk, Tea, Coffee, Orange Juice, Water};
enum CIGAR = {OldGold, Kools, Chesterfields, LuckyStrikes, Parliaments};
enum PET = {Dog, Snails, Fox, Horse, Zebra};

int: N = 5;

array[1..N] of var COLOR: color;
array[1..N] of var NATIONALITY: nationality;
array[1..N] of var DRINK: drink;
array[1..N] of var CIGAR: cigar;
array[1..N] of var PET: pet;

constraint nationality[1] == Norwegian;
constraint drink[3] == Milk;

constraint color[nationality.index(Englishman)] == Red;
constraint pet[nationality.index(Spaniard)] == Dog;
constraint drink[color.index(Green)] == Coffee;
constraint nationality[color.index(Green)] == Ukrainian;
constraint color[color.index(Green)] == color[color.index(Ivory) + 1];
constraint pet[cigar.index(OldGold)] == Snails;
constraint cigar[color.index(Yellow)] == Kools;
constraint drink[nationality.index(Ukrainian)] == Tea;
constraint drink[cigar.index(LuckyStrikes)] == OrangeJuice;
constraint nationality[cigar.index(Japanese)] == Parliaments;
constraint color[nationality.index(Norwegian)] == color[1];

constraint forall(i in 1..N)(forall(j in 1..N)(i != j -> color[i] != color[j]));
constraint forall(i in 1..N)(forall(j in 1..N)(i != j -> nationality[i] != nationality[j]));
constraint forall(i in 1..N)(forall(j in 1..N)(i != j -> drink[i] != drink[j]));
constraint forall(i in 1..N)(forall(j in 1..N)(i != j -> cigar[i] != cigar[j]));
constraint forall(i in 1..N)(forall(j in 1..N)(i != j -> pet[i] != pet[j]));

constraint forall(i in 1..N-1)(cigar.index(Chesterfields) == (i + 1) \/ 
    pet.index(Fox) == (i + 1));
constraint forall(i in 1..N-1)(cigar.index(Kools) == (i + 1) \/ 
    pet.index(Horse) == (i + 1));

include "globals.mzn";

enum COLOR = { Blue, Red, Green };
enum ANIMAL = { Dog, Cat, Zebra };

array[1..3] of var COLOR: houseColor;
array[1..3] of var ANIMAL: houseAnimal;

% Constraints
constraint houseAnimal[2] == Cat; % The Cat lives in the Red House.
constraint houseColor[2] == Red; % The Red House is the middle house.
constraint houseColor[1] == Blue /\ houseColor[2] == Red; % The Blue House is directly to the left of the Red House.
constraint houseAnimal[1] == Dog; % The Dog lives in the Blue House.
constraint alldifferent(houseColor); % Each house has a unique color.
constraint alldifferent(houseAnimal); % Each house is home to a unique animal.

include "globals.mzn";

enum GameOptions = { Paper, Rock, Scissors };

var GameOptions: playerChoice;
var GameOptions: opponentChoice;

constraint opponentChoice = Rock;
constraint playerChoice = Paper /\ (opponentChoice = Rock);

constraint playerChoice in GameOptions;
constraint opponentChoice in GameOptions;

include "globals.mzn";

enum Suspects = { MissScarlett, ColonelMustard, ProfessorPlum };
enum Weapons = { Candlestick, Revolver, Rope };
enum Rooms = { Kitchen, Library, Conservatory };

var Suspects: culprit;
var Weapons: murderWeapon;
var Rooms: murderRoom;

constraint culprit != ColonelMustard;
constraint culprit != MissScarlett;
constraint murderWeapon != Revolver;
constraint murderWeapon != Rope;
constraint murderRoom != Kitchen;
constraint murderRoom != Library;

% Each suspect, weapon, and room is unique in this scenario
constraint forall(s1 in Suspects)(forall(s2 in Suspects)(s1 != s2 -> s1 != culprit));
constraint forall(w1 in Weapons)(forall(w2 in Weapons)(w1 != w2 -> w1 != murderWeapon));
constraint forall(r1 in Rooms)(forall(r2 in Rooms)(r1 != r2 -> r1 != murderRoom));

include "globals.mzn";

enum LETTERS = {S, E, N, D, M, O, R, Y};

array[LETTERS] of var 0..9: digits;

constraint alldifferent(digits);

constraint digits[S] >= 1;
constraint digits[M] >= 1;

constraint (1000 * digits[S] + 100 * digits[E] + 10 * digits[N] + digits[D]) + 
            (1000 * digits[M] + 100 * digits[O] + 10 * digits[R] + digits[E]) = 
            (10000 * digits[M] + 1000 * digits[O] + 100 * digits[N] + 10 * digits[E] + digits[Y]);

constraint digits[M] = 1;

constraint digits[S] = 9;

include "globals.mzn";

enum Direction = {North, South, East, West};

array[1..5] of var Direction: participants;

constraint participants[1] = East /\
          participants[2] = South /\
          participants[3] = North /\
          participants[4] = West /\
          participants[5] = East;

constraint (participants[2] < participants[1]) /\ (participants[5] < participants[1]) /\ (participants[3] = participants[4]) 
          /\ (participants[2] < participants[3]) /\ (participants[4] < participants[5]);

include "globals.mzn";

enum CreditScore = 300..850;

var CreditScore: priyaCreditScore = 680;
var CreditScore: samCreditScore = 750;

int: combinedMonthlyIncome = 9000;
int: combinedMonthlyDebt = 3200;
var int: requestedLoanAmount;

var CreditScore: creditTier = min(priyaCreditScore, samCreditScore);

constraint (creditTier < 600) -> (requestedLoanAmount < 0);

var float: dtiRatio = combinedMonthlyDebt / float(combinedMonthlyIncome);
constraint dtiRatio <= 0.43 -> (requestedLoanAmount < 0);

constraint (creditTier >= 600) /\ (dtiRatio <= 0.43) -> (requestedLoanAmount <= combinedMonthlyIncome * 0.4) -> (requestedLoanAmount > 0);
constraint (creditTier >= 600) /\ (dtiRatio <= 0.43) /\ (requestedLoanAmount > combinedMonthlyIncome * 0.4) -> (requestedLoanAmount > 0);

include "globals.mzn";

enum TIME_MEDICATION = {9, 11, 16}; % times for medications (9am, 11am, 4pm)
enum TIME_MEAL = {8, 13}; % times for meals (8am, 1pm)

array[1..3] of var TIME_MEDICATION: drugTime; % times of administration for Drug A, Drug B, Drug C
array[1..2] of var TIME_MEAL: mealTime; % times of meals 

% Constraints
constraint drugTime[2] >= drugTime[1] + 4; % Drug B must be taken at least 4 hours after Drug A
constraint forall(i in 1..3) (
    (drugTime[3] >= mealTime[1] + 2) /\ (drugTime[3] >= mealTime[2] + 2)
);

constraint drugTime[3] != 9; % Drug C cannot be taken at 9am 
constraint drugTime[3] != 11; % Drug C cannot be taken at 11am 

% Drug C must be taken at 4pm by elimination of the other time slots available
constraint drugTime[3] = 16;

% The remaining time slots for Drugs A and B are 9am and 11am
constraint forall(i in 1..2)(drugTime[i] in {9, 11});

% If Drug A is taken at 9am, Drug B must be taken at 1pm to satisfy the 4-hour gap - not a valid option
constraint (drugTime[1] = 9) -> (drugTime[2] != 13); 

% If Drug A is taken at 11am, Drug B cannot be taken at 9am
constraint (drugTime[1] = 11) -> (drugTime[2] != 9);

include "globals.mzn";

enum OCCUPANTS = {Ana, Bo, Cy};
array[1..3] of var 1..3: houseNumber;
array[1..3] of var OCCUPANTS: occupant;

constraint occupant[1] = Ana;
constraint occupant[2] != Bo;
constraint alldifferent(occupant);
constraint alldifferent(houseNumber);

include "globals.mzn";

enum COLOR = {Red, Blue, Green, Yellow, White};

array[1..5] of var COLOR: houseColor;

constraint houseColor[1] = Red;
constraint houseColor[4] = White;

constraint exists(i in 1..4)(houseColor[i] = Blue /\ houseColor[i+1] = Green) \/ 
            exists(i in 1..4)(houseColor[i] = Green /\ houseColor[i+1] = Blue);

constraint alldifferent(houseColor);

constraint forall(i in 2..3)(
    (houseColor[i] = Blue) \/
    (houseColor[i] = Green)
);

constraint houseColor[5] = Yellow \/ 
              houseColor[5] != houseColor[1] /\ 
              houseColor[5] != houseColor[2] /\ 
              houseColor[5] != houseColor[3] /\ 
              houseColor[5] != houseColor[4];

include "globals.mzn";

enum GroceryItem = { ice_cream, beans, flour, bananas };
enum Compartment = { comp1, comp2, comp3, comp4 };

array[GroceryItem] of var Compartment: item_locations;

constraint forall(i in GroceryItem)( forall(j in GroceryItem where i != j)( item_locations[i] != item_locations[j]) );

constraint item_locations[ice_cream] == comp1;

constraint item_locations[beans] != comp1;
constraint item_locations[flour] != comp1;
constraint item_locations[bananas] != comp1;

include "globals.mzn";

enum ANIMALS = {tortoise, parrot, goat, rabbit, wolf};
array[ANIMALS] of var 1..5: pens;

% Domain assignments
pens[tortoise] = 1;
pens[parrot] = 2;
pens[goat] = 3;

% Rabbit and Wolf can be in Pen 4 or Pen 5
pens[rabbit] in {4, 5};
pens[wolf] in {4, 5};

% Constraints
constraint pens[tortoise] = 1;
constraint pens[parrot] = 2;
constraint pens[goat] = 3;
constraint pens[rabbit] < pens[wolf];
constraint pens[rabbit] = pens[wolf];  % As they occupy separate pens, this should be <= not equals
constraint alldifferent([pens[animal] | animal in ANIMALS]);
